//   To-dos   – ID | Task | Who (Noam / Couple) | Due (DD/MM/YYYY) | Done (Yes) | Done By | Done At
//   Info     – Title | Only Noam (Yes) | Text
//   Vendors  – Role | Name | Phone
// The couple never receives "!" lines, Noam's to-dos, "Only Noam" cards or vendors. Only Noam edits; the couple ticks their own to-dos.
// The template for new plans is the file "KAI Plan Template.json" in KAI EVENTS.
var PLAN_TABS = { 'Timeline': ['Timeline'], 'To-dos': ['ID', 'Task', 'Who', 'Due', 'Done', 'Done By', 'Done At'], 'Info': ['Title', 'Only Noam', 'Text'], 'Vendors': ['Role', 'Name', 'Phone'] };
